// Reads the WAHA webhook and keeps only direct chat messages from customers.
const input = $input.first().json;
const body = input.body || input;
if (body.event !== 'message') return [];
const m = body.payload || {};
if (m.fromMe) return [];
const chatId = m.from || '';
if (!chatId || chatId.endsWith('@g.us') || chatId.includes('status@broadcast') || chatId.endsWith('@newsletter')) return [];

const text = (m.body || '').trim();
if (!text && !m.hasMedia) return [];

return [{
  json: {
    session: body.session || 'default',
    chatId,
    // Plain number (62812...) when WAHA reports a normal chat id; null for @lid ids.
    phone: chatId.endsWith('@c.us') ? chatId.slice(0, -5) : null,
    messageId: m.id || null,
    text,
    hasMedia: !!m.hasMedia,
    receivedAt: m.timestamp ? new Date(m.timestamp * 1000).toISOString() : new Date().toISOString(),
  },
}];

// ===== CONFIG (edit these; WAHA URL + API key live in the n8n WAHA credential) =====
const CFG = {
  greetAfterHours: 12,                     // show greeting+menu again after this idle time
  humanHours: 2                            // bot stays silent this long after "operator" is chosen
};

const GREETING = 'Halo! Selamat datang di *Nikkou Hydrogen Life (日紅氫生活)* 🌸\nSaya asisten otomatis kami.';
const MENU =
'Silakan balas dengan angka untuk memilih layanan:\n\n' +
'1️⃣ Program Warisan Berbagi・Seminar Kedokteran Hidrogen\n' +
'2️⃣ Kebanggaan Taiwan・Pelopor Hidrogen Global\n' +
'3️⃣ Panduan Penggunaan Mesin Gas Hidrogen & Air Hidrogen\n' +
'4️⃣ Pusat Pengetahuan Kedokteran Hidrogen\n' +
'5️⃣ Toko Online Nikkou\n' +
'6️⃣ Pertanyaan Umum (FAQ)\n' +
'7️⃣ Bicara dengan Operator\n\n' +
'Ketik "menu" atau 0 kapan saja untuk melihat menu ini lagi.';

// Answers per option. Replace the example.com links with real ones.
const R = {
  '1': '*Program Warisan Berbagi・Seminar Kedokteran Hidrogen*\nInformasi seminar dan pendaftaran: https://www.nikkouh2.com\n\nBalas 0 untuk kembali ke menu utama',
  '2': '*Kebanggaan Taiwan・Pelopor Hidrogen Global*\nKisah merek kami: https://www.nikkouh2.com\n\nBalas 0 untuk kembali ke menu utama',
  '3': '*Panduan Penggunaan*\nVideo dan panduan bergambar mesin gas hidrogen / air hidrogen: https://example.com/tutorial\n\nBalas 0 untuk kembali ke menu utama',
  '4': '*Pusat Pengetahuan Kedokteran Hidrogen*\nPenelitian dan artikel: https://example.com/knowledge\n\nBalas 0 untuk kembali ke menu utama',
  '5': '*Toko Online Nikkou*\nBelanja online: https://example.com/shop\n\nBalas 0 untuk kembali ke menu utama',
  '6': '*Pertanyaan Umum*\nT: Bagaimana cara mulai memakai mesin gas hidrogen?\nJ: Silakan lihat panduan di menu 3.\n\n(Tambahkan Q&A lain di sini)\n\nBalas 0 untuk kembali ke menu utama',
  '7': 'Baik, operator kami sudah diberi tahu, mohon tunggu sebentar 🙏\n(Jam layanan: Senin–Jumat 09.00–18.00 WIB)\nUntuk kembali ke menu otomatis, ketik "menu".'
};

// ===== SUBMENUS =====
// A menu option can open a submenu. While it is open (SUB_MINUTES), the digits pick its options;
// 0 or "menu" goes back to the main menu. Add more by giving an option a SUB entry plus R['x.y'] texts.
const SUB_MINUTES = 30;
const SUB = {
  '3': { '1': '3.1', '2': '3.2' }
};
R['3'] = '*Panduan Penggunaan*\nPilih panduan yang Anda perlukan:\n\n1️⃣ Memakai mesin gas hidrogen (hirup)\n2️⃣ Minum air hidrogen (3 langkah)\n\nBalas angka pilihan Anda, atau 0 untuk kembali ke menu utama';
R['3.1'] = '*Memakai mesin gas hidrogen*\n1. Sambungkan ke listrik.\n2. Buka tutup tangki air, isi dengan air murni.\n3. Pasang inti filter, lalu tutup kembali tangki air.\n4. Tarik sumbat pembuangan oksigen.\n5. Tekan lama tombol daya selama 5 detik untuk masuk mode aktivasi (untuk pemakaian pertama atau setelah lama tidak dipakai).\n6. Sambungkan dan pasang selang hidung.\n7. Tekan tombol daya.\n\nBalas 2 untuk panduan air hidrogen, atau 0 untuk menu utama';
R['3.2'] = '*Minum air hidrogen (3 langkah)*\n1. Sambungkan kabel daya gelas dan selang masuk hidrogen.\n2. Tekan tombol daya mesin hidrogen, lalu tunggu sampai muncul gelembung di dalam gelas.\n3. Tekan tombol daya gelas dan tunggu 2 menit.\n\nBalas 1 untuk panduan mesin gas hidrogen, atau 0 untuk menu utama';

// ===== INPUT =====
const parsed = $('Parse Inbound').first().json;
const web = $input.first().json || {};

// 1) The web app decides first. It owns replies from customers in a follow-up,
//    safety warnings and stop requests. If it handled the message, the bot only
//    sends the text the web app returned (or stays silent).
if (web.handled === true) {
  const webReply = String(web.reply || '').trim();
  if (!webReply) return [];
  return [{ json: { session: parsed.session, chatId: parsed.chatId, reply: webReply, useAI: false, userText: parsed.text, source: 'web' } }];
}

// 2) Everyone else (and any message the web app could not check) gets the original bot.
const chatId = parsed.chatId;
if (!parsed.text) return [];               // photo or voice note without text: leave it to a human

const raw = parsed.text.normalize('NFKC').trim().toLowerCase();
const key = raw.replace(/[\s.。、,，]/g, '');
const isMenuWord = ['0', 'menu', 'hi', 'hai', 'halo', 'hello', 'mulai', 'start', 'p', 'assalamualaikum'].includes(key);

// ===== STATE (works only when workflow is ACTIVE) =====
const s = $getWorkflowStaticData('global');
s.lastSeen = s.lastSeen || {};
s.human = s.human || {};
s.sub = s.sub || {};
const now = Date.now();

// operator handover: stay silent until timeout or user asks for menu
if (s.human[chatId] && now < s.human[chatId]) {
  if (key === '0' || key === 'menu') { delete s.human[chatId]; }
  else { return []; }
}

const first = !s.lastSeen[chatId] || (now - s.lastSeen[chatId]) > CFG.greetAfterHours * 3600 * 1000;
s.lastSeen[chatId] = now;

// ===== DECIDE REPLY =====
// Fixed answers for menu options + greeting; everything else goes to the AI Agent.
let reply = '';
let useAI = false;

// A submenu is open for this chat: digits pick its options; 0 or "menu" closes it.
const open = s.sub[chatId] && now < s.sub[chatId].until ? s.sub[chatId].menu : null;
if (!open) delete s.sub[chatId];
if (open && (key === '0' || key === 'menu')) delete s.sub[chatId];
const inSub = open && key !== '0' && key !== 'menu' && SUB[open] && SUB[open][key];

if (inSub) {
  reply = R[SUB[open][key]];
  s.sub[chatId] = { menu: open, until: now + SUB_MINUTES * 60 * 1000 };   // keep it open
} else if (R[key]) {
  reply = R[key];
  if (key === '7') s.human[chatId] = now + CFG.humanHours * 3600 * 1000;
  if (SUB[key]) s.sub[chatId] = { menu: key, until: now + SUB_MINUTES * 60 * 1000 };
} else if (first) {
  reply = GREETING + '\n\n' + MENU;          // first contact -> greeting + menu
} else if (isMenuWord) {
  reply = MENU;
} else {
  useAI = true;                              // free-text question -> AI Agent
}

return [{ json: { session: parsed.session, chatId, reply, useAI, userText: parsed.text, source: 'bot' } }];

// Follow-ups are only sent during the daytime window set in the Config node (Jakarta time).
const cfg = $('Config').first().json;
const hour = Number(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta', hour: 'numeric', hour12: false })) % 24;
if (hour < Number(cfg.sendFromHour) || hour >= Number(cfg.sendUntilHour)) return [];
return [{ json: { hour } }];

// One item per message that is due. The web app only returns customers who opted in to WhatsApp;
// this double-checks that and drops anything incomplete (it stays "due" on the web side).
const res = $input.first().json || {};
const items = Array.isArray(res.items) ? res.items : [];
return items
  .filter((i) => i && i.id && i.chat_id && i.text && i.consent_whatsapp === true)
  .slice(0, 20)
  .map((i) => ({ json: i }));
